package com.alsafa.native4;
import android.app.*;import android.content.Intent;import android.net.Uri;import androidx.core.content.FileProvider;import com.alsafa.native4.core.SaleInvoicePdfWriter;import android.database.Cursor;import android.os.Bundle;import android.view.*;import android.widget.*;import com.alsafa.native4.core.CoreDb;import com.alsafa.native4.core.SaleInvoiceSnapshotStore;import java.text.*;import java.util.*;
/** Read-only sale/repair detail page. Never mutates accounting or sync state. */
public final class RecordDetailActivity extends Activity{private CoreDb db;private TextView title,header,status;private LinearLayout rows;
 public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_record_detail);db=new CoreDb(this);title=findViewById(R.id.detailTitle);header=findViewById(R.id.detailHeader);status=findViewById(R.id.detailStatus);rows=findViewById(R.id.detailRows);findViewById(R.id.pageBack).setOnClickListener(v->finish());String type=getIntent().getStringExtra("record_type"),id=getIntent().getStringExtra("record_id");try{if("REPAIR".equals(type))repair(id);else sale(id);}catch(Exception e){status.setText("تعذر فتح السجل: "+msg(e));}}
 private void sale(String id){SaleInvoiceSnapshotStore.Snapshot x=new SaleInvoiceSnapshotStore(db).get(id);title.setText("🧾 فاتورة مبيع");String customer=x.customerName,phone=x.customerPhone;header.setText("رقم الفاتورة: "+x.invoiceNo+"\nالتاريخ: "+date(x.businessAt)+"\nالعميل: "+(customer.isEmpty()?"بدون عميل محدد":customer)+(phone.isEmpty()?"":" — "+phone)+"\nالإجمالي: "+fmt(x.total)+" "+x.currency+"\nالخصم: "+fmt(x.discount)+"\nالضريبة: "+fmt(x.tax)+"\nحالة الدفع: "+paymentLabel(x.paymentStatus));for(SaleInvoiceSnapshotStore.Item i:x.items)row("⌚ "+i.description+"\nالكمية: "+i.quantity+" — سعر الوحدة: "+fmt(i.unitPrice)+" — الإجمالي: "+fmt(i.total));for(SaleInvoiceSnapshotStore.Payment p:x.payments)row("💳 "+fmt(p.amount)+" "+p.currency+" — "+p.method+(p.account==null||p.account.isEmpty()?"":" — "+p.account));if(!x.warranty.isEmpty())row("🛡 الضمان: "+x.warranty);if(!x.notes.isEmpty())row("📝 ملاحظات: "+x.notes);Button share=new Button(this);share.setText("📄 مشاركة فاتورة PDF");rows.addView(share);share.setOnClickListener(v->{share.setEnabled(false);share.setText("جاري تجهيز PDF...");new Thread(()->{try{java.io.File file=SaleInvoicePdfWriter.write(getApplicationContext(),x);runOnUiThread(()->{share.setEnabled(true);share.setText("📄 مشاركة فاتورة PDF");if(isFinishing()||isDestroyed())return;try{Uri uri=FileProvider.getUriForFile(this,getPackageName()+".files",file);Intent send=new Intent(Intent.ACTION_SEND);send.setType("application/pdf");send.putExtra(Intent.EXTRA_STREAM,uri);send.setClipData(android.content.ClipData.newRawUri("فاتورة الصفا",uri));send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(send,"مشاركة فاتورة المبيع"));}catch(Exception e){showPdfError(e);}});}catch(Exception e){runOnUiThread(()->{share.setEnabled(true);share.setText("📄 مشاركة فاتورة PDF");if(!isFinishing()&&!isDestroyed())showPdfError(e);});}},"alsafa-invoice-pdf").start();});status.setText("عرض فقط — مشاركة PDF لا تعدل الحسابات أو المزامنة.");}
 private void repair(String id){try(Cursor c=db.db().rawQuery("SELECT invoice_no,customer_name,COALESCE(customer_phone,''),watch_description,status,total,currency,received_at FROM repairs WHERE repair_id=? AND deleted_at IS NULL",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("الصيانة غير موجودة");title.setText("🛠 تفاصيل الصيانة");String customer=c.getString(1),phone=c.getString(2);header.setText("رقم الصيانة: "+c.getString(0)+"\nالتاريخ: "+date(c.getLong(7))+"\nالعميل: "+(customer.isEmpty()?"بدون عميل محدد":customer)+(phone.isEmpty()?"":" — "+phone)+"\nالساعة / العطل: "+c.getString(3)+"\nالحالة: "+c.getString(4)+"\nالقيمة: "+fmt(c.getDouble(5))+" "+c.getString(6));}try(Cursor c=db.db().rawQuery("SELECT description,quantity,unit_cost FROM repair_parts WHERE repair_id=? ORDER BY created_at",new String[]{id})){while(c.moveToNext())row("🔧 "+c.getString(0)+"\nالكمية: "+c.getInt(1)+" — تكلفة القطعة: "+fmt(c.getDouble(2)));}status.setText("عرض فقط — التحصيل والتسليم يتمان من صفحة تسليم الساعات.");}
 private static String paymentLabel(String state){if("PAID".equals(state))return "مدفوعة";if("PARTIAL".equals(state))return "مدفوعة جزئياً";if("DUE".equals(state))return "غير مدفوعة";return state==null?"غير محددة":state;}
 private void showPdfError(Exception e){new AlertDialog.Builder(this).setMessage("تعذر إنشاء أو مشاركة PDF: "+msg(e)).setPositiveButton("حسناً",null).show();}
 private void row(String s){TextView t=new TextView(this);t.setText(s);t.setGravity(Gravity.END);t.setPadding(dp(12),dp(12),dp(12),dp(12));t.setBackgroundResource(R.drawable.alsafa_card);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(5),0,dp(5));rows.addView(t,lp);}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private static String fmt(double v){return String.format(Locale.US,"%.2f",v);}private static String date(long x){return new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(new Date(x));}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}}
